window.__saqPaperQuestions("2022-2-pah",[{"number":1,"title":"","stemText":"A 60 year old man has presented with pleuritic chest pain and dyspnoea for the last 6 hours. There is no history of trauma. His chest x-ray is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 3 distinct pathologies present on the chest x-ray. Provide one supportive radiographic abnormality for each. (6 marks) Pathology Supportive radiographic abnormality"},{"id":"b","label":"Part B","prompt":"State 3 findings from your clinical assessment that would indicate the requirement for\ninsertion of an intercostal catheter in the ED. (3 marks) 1) 2) 3)"},{"id":"c","label":"Part C","prompt":"State 3 findings from your clinical assessment that would be contra-indications to the\ninsertion of an intercostal catheter in the ED. (3 marks) 1) 2) 3)"}],"propPages":["asset:img0fe8ef701489a7f482"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Visible pleural line with absent lung markings</td><td></td></tr><tr><td>Pleural thickening / plaque</td><td>Broad opacification (widespread) along right visceral pleura</td></tr><tr><td>Right sided pleural effusion</td><td>Loss of right hemidiphragm with meniscus sign</td></tr><tr><td>(accept consolidation w effusion)</td><td></td></tr><tr><td>Increased interstitial markings right lung</td><td></td></tr><tr><td>Interstitial lung disease</td><td></td></tr><tr><td>Progressive hypoxia despite supplemental O2</td><td></td></tr><tr><td>Worsening fatigue as evidenced by resp acidosis (or surrogate)</td><td></td></tr><tr><td>Progressive pneumothorax ie on serial CXR</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Patient refusal</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Pleural thickening / plaque</div><div class=\"answer-line\">Broad opacification (widespread) along right visceral pleura</div><div class=\"answer-line\">Loss of right hemidiphragm with meniscus sign</div><div class=\"answer-line\">Right sided pleural effusion</div><div class=\"answer-line\">(accept consolidation w effusion)</div><div class=\"answer-line\">Increased interstitial markings right lung</div><div class=\"answer-line\">Interstitial lung disease</div><div class=\"answer-line\">2</div><div class=\"answer-line\">Progressive hypoxia despite supplemental O2</div><div class=\"answer-line\">Worsening fatigue as evidenced by resp acidosis (or surrogate)</div><div class=\"answer-line\">Progressive pneumothorax ie on serial CXR</div><div class=\"answer-line\">Patient refusal</div><div class=\"answer-line\">Iatrogenic Coagulopathy (ie presence of DOAC/warfarin)</div><div class=\"answer-line\">Marked thrombocytopaenia</div><div class=\"answer-line\">Active malignancy with risk dissemination</div><div class=\"answer-line\">Established ceiling of care stating not for invasive interventions</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 14 year old girl has presented after an intentional overdose of insulin.","parts":[{"id":"a","label":"Part A","prompt":"List 4 key features of your history that will influence your toxicological risk assessment of her presentation. Provide justification for each. (4 marks) Key feature of history Justification Your risk assessment is consistent with a potentially lethal overdose. The patient has hypoglycaemia."},{"id":"b","label":"Part B","prompt":"List 3 other biochemical complications of insulin overdose. (3 marks)\n1) 2) 3) History has revealed that the patient is not diabetic. The insulin belongs to her mother."},{"id":"c","label":"Part C","prompt":"State how the patient’s non-diabetic status impacts the downstream management of her\n• verdose, in comparison with managing an insulin overdose in a diabetic patient. (1 mark)\nThe patient’s mother has presented to triage demanding to see her. The patient has stated she does not wish for her mother to be contacted about her attendance."},{"id":"d","label":"Part D","prompt":"State three key considerations in determining whether to permit the mother into her daughter’s treatment bay. (3 marks) 1) 2) 3)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Type of Insulin (ie long-acting vs short acting) – may impact time to toxicity and duration</td><td>Usual Insulin regime and requirements – may impact suspicion of toxic risk of dose not &gt;&gt; usual dose</td></tr><tr><td><strong>Time of overdose</strong> (and timing ie single vs staggered) – expectation of peak toxicity and caution</td><td>needed if staggered overdose</td></tr><tr><td>Location of injection (ie depot vs multiple sites) – pharmacokinetics less predictable for large single</td><td>depot site</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hypophosphataemia</div><div class=\"answer-line\">Hypomagnesaemia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">In non-type 1 diabetics, exogenous glucose can stimulate endogenous insulin release and can</div><div class=\"answer-line\">produce rebound hypoglycaemia which can make ceasing treatments challenging</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">The child’s response to hearing her mother is present (does she now want her in the room)</div><div class=\"answer-line\">Is the mother the child’s legal guardian (is she emancipated)</div><div class=\"answer-line\">Does the child have capacity to refuse based on the circumstances of the situation and issue (is she</div><div class=\"answer-line\">currently hypoglycaemic and impaired)</div><div class=\"answer-line\">Clear discussion around confidentiality if child deemed competent</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 62 year old man has presented to ED with recurrent syncope. His history is relevant for prior pacemaker insertion for third degree AV block. An ECG is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State your conclusion from the ECG. Provide 3 supportive ECG findings. (4 marks) Conclusion ECG findings 1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List 4 investigations you would perform. Provide justification for each. (4 marks)"},{"id":"c","label":"Part C","prompt":"State 3 findings on further assessment that would indicate the need to initiate electrical pacing in this patient. (3 marks) 1) 2) 3)"}],"propPages":["asset:imgd5a7eaa88b8e7b8c15"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Ventricular pacing with intermittent, recurrent <strong>Failure to capture</strong></div><div class=\"answer-line\">ECG findings:</div><div class=\"answer-line\">Regular endogenous atrial activity</div><div class=\"answer-line\">Lack of native ventricular activity</div><div class=\"answer-line\">Associated appropriate V pacing spikes</div><div class=\"answer-line\">Lack of mechanical capture after some of the pacing spikes</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>K – to ensure no hyperkalaemia impairing cardiac function</td><td>pH – acidosis can interfere with capture and pacing effectiveness</td></tr><tr><td>Troponin – ischaemia can impair electrical function and interfere with pacemaker effect</td><td>Pacemaker check – if battery failing or increased resistance from lead fibrosis/scarring may lead to</td></tr><tr><td>decreased output and failure to capture</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Impaired mentation (new) – confusion/ALOC</div><div class=\"answer-line\">Refractory hypotension – SBP &lt;90mmHg</div><div class=\"answer-line\">Pulmonary oedema from left sided heart failure</div><div class=\"answer-line\">Angina from poor coronary perfusion</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 52 year old man has presented with dyspnoea at rest. You note in the chart he was discharged 5 days prior after having a mitral valve replacement for rheumatic heart disease.","parts":[{"id":"a","label":"Part A","prompt":"List 5 potential causes of his dyspnoea that can be identified by bedside ultrasound.\nInclude the key ultrasound finding/s for each. (10 marks) Cause Ultrasound finding/s"},{"id":"b","label":"Part B","prompt":"List 3 other investigations you would perform. Provide justification for each. (3 marks)\n1) 2) 3)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>LV Failure – decreased LV function with pulmonary congestion (decreased EF, dilated LV, B lines,</td><td>effusions)</td></tr><tr><td>Paravalvular leak with acute MR (dilated LA, dynamic LV) (transvalv colour jet (retrograde during</td><td>systole, dilated LA, pulmonary congestion)</td></tr><tr><td>Valve Thrombosis with Left atrial dilation and poor LV filling (small hypodynamic LV with large LA</td><td>and minimal colour flow across valve (may see thrombus at LV inlet region)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Hb – identify anaemia (common post op)</td><td>Renal Function – may have AKI from operation, new meds ie ACE-I</td></tr><tr><td>Coagulation profile – if on warfarin for mitral valve, will alter risk of valve thrombosis</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 37 year old female has been brought to ED after being punched repeatedly by her domestic partner. The patient has bruising and swelling around her left face and eye.","parts":[{"id":"a","label":"Part A","prompt":"State 8 features of your examination, including the specific injury for which you will be\nassessing. (8 marks) Examination feature Specific injury The patient has sustained facial bruising without more serious physical injury. The patient does not wish to report the incident to the police."},{"id":"b","label":"Part B","prompt":"State 4 management priorities for this patient. (4 marks)\n1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Eye exam</div><div class=\"answer-line\">IOP – Hyphaema with resultant raised IOP/glaucoma</div><div class=\"answer-line\"><strong>Visual Acuity</strong> – commotio with retinal haemorrhage</div><div class=\"answer-line\">EOM – entrapment with loss of upward gaze due to blowout fracture</div><div class=\"answer-line\">Slit Lamp – hyphaema</div><div class=\"answer-line\">Diplopia from blowout fracture (ie enopthalmus)</div><div class=\"answer-line\">Ear exam</div><div class=\"answer-line\">Tympanic Membrane perforation</div><div class=\"answer-line\">Dental exam</div><div class=\"answer-line\">Dental Fractures/trauma requiring specific cares</div><div class=\"answer-line\">Mandibular exam to exclude fracture ie malocclusion/trismus</div><div class=\"answer-line\">C-spine exam</div><div class=\"answer-line\">Midline tenderness or peripheral neurologic signs concerning for nerve root injury/cord</div><div class=\"answer-line\">injury</div><div class=\"answer-line\">Nasal exam to exclude fracture/ septal haematoma</div><div class=\"answer-line\">Facial sensation to exclude infraorbital nerve dysfunction</div><div class=\"answer-line\">Examination for base of skull fracture (any specific sign)</div><div class=\"answer-line\">Assessment of GCS/consciousness – intracranial injury</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Confidentiality</div><div class=\"answer-line\">No patient information to be provided at triage/over phone</div><div class=\"answer-line\">Documentation</div><div class=\"answer-line\">Offer social work/allied health supports</div><div class=\"answer-line\"><strong>Ensure safe discharge disposition </strong>or SSW if no safe discharge option for now</div><div class=\"answer-line\">Non-judgemental approach</div><div class=\"answer-line\">Provide information such that can access police/legal if changes mind</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"Search and Rescue have notified you of a male patient en route to hospital who was separated from his back-country ski tour. He has been outside for over 24 hours. The retrieval team have reported his temperature as 26 degrees celsius.","parts":[{"id":"a","label":"Part A","prompt":"State 3 ECG changes commonly seen in profound hypothermia. (3 marks)\n1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List 3 body systems (other than cardiovascular) that may be affected by hypothermia.\nProvide a cardinal effect seen for each. (3 marks) Body system Effect On arrival, the patient appears to have frostbite of both hands."},{"id":"c","label":"Part C","prompt":"Complete the table for signs of frostbite injury. (4 marks) Degree of frostbite injury Specific examination findings First degree Second degree Third degree Fourth degree"},{"id":"d","label":"Part D","prompt":"Regarding the ED management of frostbite, provide the following details: (2 marks) Rewarming method End-point of re-warming"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">T wave inversion</div><div class=\"answer-line\">PR/ QRS/ QT prolongation</div><div class=\"answer-line\">Osborne (J) waves</div><div class=\"answer-line\">Sinus brady</div><div class=\"answer-line\">Atrial Fibrillation</div><div class=\"answer-line\">AV block</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Resp – bronchorrhoea, depression cough and gag reflexes</td><td>CNS – incordination, confusion, lethargy, coma (dilated, fixed pupils)</td></tr><tr><td>Renal – cold-induced diuresis</td><td>Haem – DIC, intravascular thrombosis and emboli</td></tr><tr><td>GIT/Biliary – Pancreatitis is common, Hepatic function is impaired leading to drug accumulation</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">1st degree – numbness, erythema, oedema, desquamation, dysethesia</div><div class=\"answer-line\">2nd degree – blisters</div><div class=\"answer-line\">3rd degree – tissue loss of entire thickness of skin</div><div class=\"answer-line\">4th degree – tissue loss beyond skin (ie deeper structures)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Method – immerse in circulating water at 40-42 deg</div><div class=\"answer-line\">End-point – until part is pliable and erythematous</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 2 year old girl has been brought to the ED with 24 hours of frequent vomiting.\nA venous blood gas is provided below.\n\npH\n7.54 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\nHCO3\nmmol/L (22 - 33)\n\nBE\n+7 mmol/L (-3 - +3)\n\nNa\n140 mmol/L (135 - 145)\n\nK\n4.0 mmol/L (3.5 - 5.2)\n\nCl\nmmol/L (95 - 110) Gluc 4.4 mmol/L (3.0 - 7.8) Lact 1.8 mmol/L (0.5 - 2.2)","parts":[{"id":"a","label":"Part A","prompt":"Interpret the results by completing the following tables. (6 marks) Primary acid-base disturbance Likely cause Secondary acid-base disturbance Likely cause Degree of compensation Formula"},{"id":"b","label":"Part B","prompt":"List 4 potential surgical causes for her presentation. Include a discriminatory finding on history or examination for each. (8 marks) Potential surgical cause Discriminatory history or examination finding Your diagnosis is viral gastroenteritis. The child appears moderately dehydrated and has not tolerated any oral rehydration.\n\nWeight is 15kg."},{"id":"c","label":"Part C","prompt":"State below your prescription for nasogastric rapid rehydration for this child. (3 marks) Fluid type Volume to be infused Rate of NG infusion"},{"id":"d","label":"Part D","prompt":"State 2 advantages of nasogastric rehydration compared with IV fluid rehydration.\n(2 marks) 1) 2) The child is admitted to the short stay ward for completion of her care."},{"id":"e","label":"Part E","prompt":"List 4 criteria you would seek for safe discharge home. (4 marks)\n1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Metabolic Alkalosis</strong> – from acid loss due to vomiting</div><div class=\"answer-line\">HAGMA – AG raised at 23</div><div class=\"answer-line\">Complete Resp compensation (calculated is 0.7 x HCO3 + 20 = 48)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td><strong>Intussusception</strong> – recurrent episodes of severe distress, associated pallor or redcurrent jelly stools</td><td>Incarcerated Hernia – known hernia, tender mass palpable in inguinal region</td></tr><tr><td><strong>Appendicitis</strong> – fever, rebound tenderness in RIF, Rovsing’s etc</td><td>Malrotation – known midgut issue/meckel’s</td></tr><tr><td>Biliary problems (atresia, PSC, PBC) Jaundice</td><td>Others likely ok here</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Type: Pedialyte/Hydrolyte/ORS/Gastrolyte (or equiv)</div><div class=\"answer-line\">Volume – 50-100mls/kg over 4 hrs (accept 750 – 1500mls)</div><div class=\"answer-line\">Rate – accept 188 – 375/hr</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Demonstrates intact gut function and improves confidence at discharge</div><div class=\"answer-line\">Likely more ‘physiological’ and allows body to adequately balance need for volume and</div><div class=\"answer-line\">elecs/nutrients through absorption</div><div class=\"answer-line\">Evidence of risks of bolus IV fluids not present with NGT RRT</div><div class=\"answer-line\">Avoids negatives of IVT – physical movement limitations, risks of IVC tissue/pain etc etc</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Parental satisfaction and confidence</div><div class=\"answer-line\">Child has normalisation of vitals/markers of hydration</div><div class=\"answer-line\">Suitable social parameters</div><div class=\"answer-line\">Time of day</div><div class=\"answer-line\">Follow up discussed and plan in place</div><div class=\"answer-line\">Discharge documentation etc</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"An 82 year old female with a history of dementia has been brought to your ED after assaulting a member of staff at her nursing home. She is clearly agitated on arrival.","parts":[{"id":"a","label":"Part A","prompt":"List 4 findings on collateral history that would support a diagnosis of acute delirium for this patient. (4 marks) 1) 2) 3) 4) Collateral history supports the presence of an acute delirium."},{"id":"b","label":"Part B","prompt":"List 4 investigations you might undertake to identify the cause of her delirium. Provide a clinical indication for the performance of each. (4 marks) Investigation Clinical indication Despite non-invasive efforts, the patient is difficult to manage and is posing a risk to herself due to her agitation."},{"id":"c","label":"Part C","prompt":"List three drugs (each from a different class) that you could employ to manage her agitation. For each class, list a potential contraindication to its use in this patient. (3 marks) Drug Potential contra-indication"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Abrupt change in behaviour/cognition/orientation</div><div class=\"answer-line\">Interruption to normal diurnal cycling</div><div class=\"answer-line\">Inattention</div><div class=\"answer-line\">Fluctuating course</div><div class=\"answer-line\">Presence of hallucinations</div><div class=\"answer-line\">Abnormal vital signs reported by carers/family (ie fevers)</div><div class=\"answer-line\">History of similar</div><div class=\"answer-line\">Recent infections (ie UTI)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">UTI – fever, reported change in urinary function (ie continence) or frequency/ symptoms (ie pain)</div><div class=\"answer-line\">Chem20 – Hx of hyponatraemia or medications consistent with low Na (ie diuretics, SSRIs etc)</div><div class=\"answer-line\">CXR – presence of tachypnoea, fever, new cough</div><div class=\"answer-line\">CT Head – history of falls, history of solid organ tumour</div><div class=\"answer-line\">CT Abdo – change in bowel function ie obsti/constipation or signs of distress on abdominal exam or</div><div class=\"answer-line\">vomiting</div><div class=\"answer-line\">COAG profile – on warfarin</div><div class=\"answer-line\">Blood Cultures – shock state ie hypotension with fever or poor perfusion</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Droperidol – parkinsons disease</td><td>Benzodiazepines ie lorazepam, diazepam – sleep apnoea,  cirrhotic liver disease</td></tr><tr><td>Risperidone – neutropaenia</td><td>Olanzapine - ????</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 25 year old motorcyclist has presented after a high speed collision with a four wheel drive. A slice from the CT scan of his abdomen with contrast is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities seen on the CT scan provided. (3 marks)\n1) 2) 3) No other injuries were identified. During the initial phase of this patient’s management, 2 units of packed red blood cells were administered. On return from the CT scanner, the patient has the following vital signs:\n\nGCS\nE4 V4 M6\n\nHR\n130 /min\n\nBP\n75/40 mmHg You are anticipating a large transfusion requirement until definitive intervention can be performed."},{"id":"b","label":"Part B","prompt":"State 2 advantages and 2 disadvantages of using a ROTEM guided massive transfusion\nprotocol (MTP) versus a ratio guided MTP. (4 marks)"},{"id":"c","label":"Part C","prompt":"List 4 potential complications of massive transfusion that you might see in the ED.\n(4 marks) 1) 2) 3) 4)\nPAH 2022.2 trial SAQ paper\nPART 2\nQuestions 10 - 18\n1 hour"}],"propPages":["asset:img3e43a21073c8184b41"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Active blush in splenic bed</div><div class=\"answer-line\"><strong>Free fluid (blood) around liver spleen </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>Advantages:</td><td>Targeted blood component replacement with potential benefit of less overall product use</td><td>Less volume use may avoid complications of MTP ie thermodilution, haemodilution, coagulopathy</td></tr><tr><td>Directed correction of identified coagulopathy allows targeted treatment ie TXA/Fibrinogen</td><td>Disadvantages</td><td>Requires regular sampling and interpretation</td></tr><tr><td>Requires specific equipment and interpretation of algorithm</td><td>Active thinking process rather than prescriptive MTP</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">TACO</div><div class=\"answer-line\">Coagulopathy from dilution</div><div class=\"answer-line\">Hypothermia</div><div class=\"answer-line\">Hypocalcaemia</div><div class=\"answer-line\">Hypomagnesaemia</div><div class=\"answer-line\">Citrate toxicity</div><div class=\"answer-line\">HAGMA</div><div class=\"answer-line\">Air embolus</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 17 year old man has presented to your rural ED following a quad bike accident where he has impacted a wire fence and sustained blunt trauma to his neck.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features on clinical examination that would be suggestive of aerodigestive tract\ninjury. (4 marks) 1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"List 4 features on clinical examination that would be suggestive of vascular injury.\n(4 marks) 1) 2) 3) 4) Your assessment is concerning for an airway injury. The patient develops stridor with the following vital signs:\n\nHR\n140 /min\n\nBP\n100/60 mmHg\n\nRR\n/min\n\nSats\n94% 15L O2 via non-rebreather mask You determine the patient requires intubation."},{"id":"c","label":"Part C","prompt":"List 6 potential difficulties that might arise during the peri-intubation period. State how you will manage each issue. (6 marks) Difficulty Management"},{"id":"d","label":"Part D","prompt":"List 3 investigations that will help delineate the extent of his injuries. Explain the utility of each. (3 marks) 1) 2) 3)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Subcut emphysema</div><div class=\"answer-line\">Crepitus at larynx/cricoid region</div><div class=\"answer-line\">Dysphonia/Aphonia</div><div class=\"answer-line\">Stridor</div><div class=\"answer-line\">Drooling</div><div class=\"answer-line\">Posturing ie sitting forward</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Expanding haematoma</div><div class=\"answer-line\">Pulsatile Haematoma</div><div class=\"answer-line\">Distal pulse deficit</div><div class=\"answer-line\">Stroke Syndrome ie hemiparesis/coma</div><div class=\"answer-line\">Bruit</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Patient position – tolerate sitting position until paralysis, then position optimally ie 30deg</div><div class=\"answer-line\">Upper airway anatomical distortion ie lateral deviation of larynx – external laryngeal</div><div class=\"answer-line\">manipulation/use of video laryngoscope with assistant to locate laryngeal inlet</div><div class=\"answer-line\">Upper airway bleeding from trauma – double suction</div><div class=\"answer-line\"><strong>Upper airway swelling</strong> – have smaller ETT ready</div><div class=\"answer-line\">Inability to pass tube/bougie through cords – prepare double setup with second operator at neck</div><div class=\"answer-line\">(may need USS given trauma) ie CI, Can Oxygenate or CICO</div><div class=\"answer-line\">Laryngospasm at induction – ensure adequate preoxygenation with addition of NPO2 @15lpm to</div><div class=\"answer-line\">NRB or BiPAP</div><div class=\"answer-line\">Conversion of partial to complete tissue injury ie tracheal laceration – ensure gentle technique and</div><div class=\"answer-line\">instrumentation, tolerate smaller tube</div><div class=\"answer-line\">Hypotension on induction – fluid load ie 10/kg 0.9% S with reasonable end-point at induction/</div><div class=\"answer-line\">reduce dose of appropriate agent ie ketamine 0.5-1mg/kg</div><div class=\"answer-line\">Hypoxia on induction – adequate preoxygenation, NPO2 throughout instrumentation/apnoea/</div><div class=\"answer-line\">accept bag through apnoea here</div><div class=\"answer-line\">Accept others around post-intubation hypotension/hypoxia</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Bronchoscopy/FNE panendoscopy for upper airway/tracheal injury</div><div class=\"answer-line\">Oesophagoscopy for digestive injury</div><div class=\"answer-line\">Could include swallow study (timing?) for oesophageal injury</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 3 month old baby has been brought in by his parents with a three day history of fever and irritability. He has developed a rash in the last 24 hours as shown in the clinical photo below.","parts":[{"id":"a","label":"Part A","prompt":"List 3 key features demonstrated in the clinical photo. (3 marks)\n1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List 3 differential diagnoses for the presentation. (3 marks)\n1) 2) 3) The patient has the following clinical signs:\n\nHR\n200 /min\n\nBP\n60/40 mmHg\n\nRR\n/min\n\nTemp\n39.2 degrees\n\nBSL\n2.8 mmol/L\n\nWeight\n6 kg"},{"id":"c","label":"Part C","prompt":"State 5 components of your management including end-points where appropriate.\n(5 marks) 1) 2) 3) 4) 5)"}],"propPages":["asset:img4988b2f3feae05bd95"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Widespread erythematous (macular) rash</div><div class=\"answer-line\">Involving trunk/face/limbs</div><div class=\"answer-line\">Associated epidermal flaking/peeling</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Drug reaction – SJS / TENS</div><div class=\"answer-line\">Kawasaki disease</div><div class=\"answer-line\">Scarlet Fever</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\"><strong>Antibiotics – fluclox dose 50mg/kg </strong></div><div class=\"answer-line\">Skin care –dressings</div><div class=\"answer-line\">Derm consult acceptable for advice on emollients</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"You are the consultant in-charge of a tertiary ED. An 87 year old man has had a cardiac arrest on the ramp and subsequently died. He had been waiting over 3 hours for an acute cubicle.","parts":[{"id":"a","label":"Part A","prompt":"List 6 factors that may have contributed to this outcome. (6 marks)\n1) 2) 3) 4) 5) 6)"},{"id":"b","label":"Part B","prompt":"State 6 components of your management of the situation. (6 marks)\n1) 2) 3) 4) 5) 6)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Ambulance Surge</div><div class=\"answer-line\">Staffing inadequacies (ie sick leave/rostering)</div><div class=\"answer-line\">Triage assessment/training ie high-risk features missed/not conveyed</div><div class=\"answer-line\">Lack of review of on-ramp patients by nursing or QAS staff</div><div class=\"answer-line\"><strong>Access block (admitted patients filling ED assessment bays) </strong></div><div class=\"answer-line\">ED Activity (ie resus activity, attention distraction/fixation on other cases)</div><div class=\"answer-line\">Communication inadequacies between triage and senior nursing/medical staff</div><div class=\"answer-line\">Patient factors (ie NESB, cognitive status)</div><div class=\"answer-line\">Others possibly ok</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Debrief staff involved</div><div class=\"answer-line\"><strong>Notify next of kin, open disclosure </strong></div><div class=\"answer-line\">Apologise to NOK for events</div><div class=\"answer-line\">Pledge to investigate</div><div class=\"answer-line\">Notify Hospital Med Super/Exec of situation</div><div class=\"answer-line\">Review case specifics and documentation</div><div class=\"answer-line\">Ensure case reported through local QA processes ie Riskman, Morbidity and Mortality, Patient Safety</div><div class=\"answer-line\">committee</div><div class=\"answer-line\">Diocument all events</div><div class=\"answer-line\">Others ok</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 55 year old woman has presented with chest pain and shortness of breath. Bedside\nechocardiogram has revealed a large pericardial effusion.","parts":[{"id":"a","label":"Part A","prompt":"List 4 potential causes for her pericardial effusion. For each, provide a discriminatory\nfeature from history or examination. (4 marks) Cause Discriminatory history or examination feature"},{"id":"b","label":"Part B","prompt":"List 3 echocardiogram findings that are consistent with pericardial tamponade. (3 marks)\n1) 2) 3) Shortly after arrival, the patient deteriorates with a loss of consciousness and no palpable pulse. The cardiac monitor reveals sinus rhythm at a rate of 110 beats per minute."},{"id":"c","label":"Part C","prompt":"State 5 components of your management. (5 marks)\n1) 2) 3) 4) 5)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Post viral – clear viral prodrome ie URTI Sx, Fever on exam</td><td>Autoimmune – history SLE or similar</td></tr><tr><td>Post Infarct – recent MI ie dressler’s syndrome</td><td>Malignant – insidious onset, hx of cancer</td></tr><tr><td>Haemorrhagic – history of anticoagulation ie supratherapeutic INR on warfarin</td><td><strong>Aortic dissection – focal neurological abnormalities </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Diastolic RV collapse</div><div class=\"answer-line\">Systolic RA collapse</div><div class=\"answer-line\">Non-varying IVC distention</div><div class=\"answer-line\">Exaggerated MV/TV inflow velocity variation with resp cycle (pulsus paradoxus)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">100% O2 via BVM</div><div class=\"answer-line\">IV Fluid load 10ml/kg 0.9% NS</div><div class=\"answer-line\"><strong>Pericardiocentesis with USS-guided needle drainage/ insertion of drain over wire </strong></div><div class=\"answer-line\">Cardiology attendance for formalisation of drain</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"An 11 year old girl has presented with an acute exacerbation of asthma.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features on initial assessment that would indicate a severe exacerbation of asthma. (4 marks) 1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"List 8 treatment measures you might use in this patient’s management. Include doses/\nend-points where appropriate. Provide a clinical indication for each. (8 marks) Treatment measure Clinical Indication"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Agitation</div><div class=\"answer-line\">Tripod position</div><div class=\"answer-line\">Talking words only</div><div class=\"answer-line\">Tachypnoea with accessory muscle use</div><div class=\"answer-line\">Sats 90-94% on air</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Salbutamol 5mg nebulised</strong>  - presence of wheeze, increased WOB</td><td>Atrovent 0.5mg neb – if clinically mod/severe</td></tr><tr><td><strong>Oxygen –</strong> indication sats &lt;94%</td><td>Magnesium Sulphate – 25mg/kg IV – clinically severe asthma not responding to simple</td></tr><tr><td>bronchodilators</td><td>Prednisolone (or HCT if given IV) 2mg/kg (4mg/kg HCT) – clear diagnosis of asthma, &gt;mild symptoms</td></tr><tr><td>Antibiotics for CAP – indication fever and focal crackles – as per eTG</td><td>NIV – CPAP or BiPAP both acceptable – as bridge to intubation if non-responsive to initial measures</td></tr><tr><td>or resp acidosis progressive</td><td>IV Fluids – if any evidence clinical dehydration – bolus 10ml/kg if evidence of shock (end-point</td></tr><tr><td>improvement in perfusion/BP etc) or maintenance if not shocked</td><td>Intubation – something reasonable</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 60 year old man has presented with epigastric abdominal pain for the past 12 hours.\nHe had a cholecystectomy 4 months ago.","parts":[{"id":"a","label":"Part A","prompt":"State 5 differential diagnoses with a discriminatory feature on history or examination for each. (5 marks) Diagnosis Discriminatory feature on Hx or Ex His liver function tests are provided below. Albumin (35-50 g/L) Bili (total) (<20 umol/L) Bili (conj) (<4 umol/L) ALP 271 (30-110 U/L) GGT 1160 (<38 U/L) ALT 246 (<34 U/L) AST 275 (<31 U/L) LDH 287 (120-250 U/L)"},{"id":"b","label":"Part B","prompt":"Provide the most likely diagnosis, with justification. (3 marks) While in the ED, the patient has become more unwell.\nHis vital signs are:\n\nHR\n110 /min\n\nBP\n70/50 mmHg\n\nRR\n/min\n\nSats\n98%\n• n room air\n\nT\n39.6 degrees\n\nGCS\nM6 V5 E3"},{"id":"c","label":"Part C","prompt":"State 4 components of your management of this patient, with justification and end-points\nwhere appropriate. (4 marks) 1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Ruptured AAA – pulsatile aneurysm in epigastrium</td><td>Pancreatitis – Hx alcohol binge/excess, positional pain, radiating through to back</td></tr><tr><td>Acute MI – radiation to Rt arm/jaw, exertional, Hx IHD</td><td>Mesenteric Ischaemia – Known procoagulant state, AF, soft abdomen</td></tr><tr><td>Peptic Ulcer disease/perforation – recent risks – steroids/NSAIDs, peritonism</td><td>Cholangitis – jaundice, fever</td></tr><tr><td>Choledocolithiasis – known CBD stones at cholangiogram</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Ascending Cholangitis (likely from stone or stricture)</div><div class=\"answer-line\">Evidenced by conjugated hyperbiliriubinaemia with elevated membrane bound (cholestatic) LFTs</div><div class=\"answer-line\">(ALP /GGT) with less elevation of intracellular (hepatitic) LFTs (AST/ALT)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia with fentanyl 25mcg repeat to comfort</div><div class=\"answer-line\"><strong>Antibiotics – ie Piptaz 4.5gm/ triples or eTG </strong></div><div class=\"answer-line\">Surgeons or Interventional Gastro for ERCP/laparotomy depending on site and availability</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 55 year old man has presented with acute atraumatic ankle pain and a low grade fever.\nA clinical photo is shown below.","parts":[{"id":"a","label":"Part A","prompt":"State 3 clinical features demonstrated in the photograph. (3 marks)\n1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List 5 differential diagnoses for his presentation. For each diagnosis, list a definitive\ninvestigation finding that would confirm its presence. (5 marks) Diagnosis Definitive investigation finding A joint aspirate is performed with the following result: Appearance Cloudy yellow\n\nWCC\n40,000 /uL %PMNs 70% Gram stain Negative Crystals negatively birefringent"},{"id":"c","label":"Part C","prompt":"State the diagnosis. (1 mark)"},{"id":"d","label":"Part D","prompt":"List 3 medications with doses, that could be used to manage this problem. Provide a\nrelative contra-indication for each. (3 marks) Medication Contra-indication"}],"propPages":["asset:imgbc8461c3ece916bc13"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Erythema at ankle extending into midfoot</div><div class=\"answer-line\">Marked swelling at lateral (visible) ankle and foot) with loss surface anatomy</div><div class=\"answer-line\">Held in plantarflexion consistent with effusion</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Gout</strong> – Ankle – neg birefringent crystals on aspirate microscopy</td><td><strong>Septic Arthritis</strong> – positive gram stain on aspirate</td></tr><tr><td>Pseudogout –calcium pyrophosphate crystals on stain</td><td>Trauma with midfoot injury ie Lisfranc injury – fracture on XR/CT with widening at LF joint</td></tr><tr><td>Haemarthrosis – frank blood on aspirate</td><td>Cellulitis – oedematous soft tissues of skin only on USS – no effusion</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Acute gout</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Colchicine – immobile patient (diarrhoea risk), Hx overdoses</td><td>Prednisolone (or equiv) – diabetic patients with poor glycaemic control, Hx psychosis</td></tr><tr><td>NSAIDs – renal failure or gastritis/PUD</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 26 year old women has presented with fever, headache and arthralgias 10 days after returning from a trip to Papua New Guinea. Her initial FBC panel is as follows:\n\nHb\ng/L (115-160)\n\nWCC\nx10^9/L (4-11) Plt x10^9/L (140-400) MCV fL (80-100)","parts":[{"id":"a","label":"Part A","prompt":"Provide the most likely explanations for the abnormalities shown. (3 marks)"},{"id":"b","label":"Part B","prompt":"List 4 further investigations you would perform, with justification. (4 marks)\n1) 2) 3) 4) Shortly after arrival, the patient has a prolonged seizure, unresponsive to benzodiazepines:\nHer vital signs are:\n\nHR\n120 /min\n\nBP\n70/40 mmHg\n\nRR\n/min\n\nSats\n90% room air\n\nT\n38.6 degrees"},{"id":"c","label":"Part C","prompt":"State 5 management priorities with end-points where appropriate. (5 marks)\n1) 2) 3) 4) 5)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>(8/12) </strong></div><div class=\"answer-line\">1.</div><div class=\"answer-line\">Malaria with RBC destruction and resultant anaemia, low platelets due to hypersplenism</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>IV Fluid – 0.9% saline 20ml/kg bolus aim MAP &gt;65 or SBP &gt;`100 </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Antimalarials – artesunate 2.4mg.kg IV</div><div class=\"answer-line\"><strong>Antibiotics (Dx not yet confirmed) including CNS cover – Ceftriaxone 50mg/kg, vanc 30mg/kg, </strong></div><div class=\"answer-line\"><strong>gent/tobra 7mg/kg </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 45 year old woman has fallen 2m from a ladder, impacting her left chest on to a pot plant. Her chest x-ray is shown below.","parts":[{"id":"a","label":"Part A","prompt":"List 3 traumatic injuries evident on the CXR, with radiographic supporting evidence.\n(3 marks) 1) 2) 3) The patient is complaining of significant left sided chest pain."},{"id":"b","label":"Part B","prompt":"List 5 treatment options for managing her pain. Include doses. (5 marks)\n1) 2) 3) 4) 5)"},{"id":"c","label":"Part C","prompt":"State 6 potential benefits of performing a CT scan of this patient’s chest. (6 marks)\n1) 2) 3) 4) 5) 6)"},{"id":"d","label":"Part D","prompt":"List 3 potential complications from this injury, apart from pain. (3 marks)\n1) 2) 3)\nPAH 2022.2 trial SAQ paper\nPART 3\nQuestions 19 - 27\n1 hour"}],"propPages":["asset:imga5c99634b44ab69f70"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Left pneumothorax – subcutaneous emphysema</div><div class=\"answer-line\">Multiple rib fractures – left lateral displaced fractures visible</div><div class=\"answer-line\">Left Haemothorax -veiling of left hemithorax (subtle)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">IV opiate ie fentanyl 50mcg repeated to comfort</div><div class=\"answer-line\">PCA ie fentanyl or oxydodone ie oxycodone 1-2mg with 5 min lockout</div><div class=\"answer-line\">Ketamine infusion</div><div class=\"answer-line\">Intercostal nerve block under USS guidance</div><div class=\"answer-line\">Serratus Anterior plane block under ultrasound</div><div class=\"answer-line\">Oral drugs – paracetamol, ibuprofen, oxycodone doses</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Identify ongoing source of bleeding – blush on CTA - eg intercostal vascular focus</div><div class=\"answer-line\">Identify other associated intra-thoracic injuries ie contusions, pulmonary lacerations</div><div class=\"answer-line\">Quantify PTX to aid decision making around need for/ type of ICC</div><div class=\"answer-line\">Quantify size of haemothorax and need for intervention</div><div class=\"answer-line\">Identify evidence of radiologic flail and inform possible need for rib fixation</div><div class=\"answer-line\">Exclude thoracic spine fracture</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Atelectasis</div><div class=\"answer-line\">Hypostatic pneumonia</div><div class=\"answer-line\">Empyema</div><div class=\"answer-line\">Progressive pneumothorax</div><div class=\"answer-line\">Pleural fibrosis – restrictive lung disease</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 52 year old man has presented with a fever and headache. You are concerned about the\npossibility of meningitis.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your examination, apart from fever, that would be consistent with\nmeningitis. (4 marks) 1) 2) 3) 4) Following initial assessment, your provisional diagnosis is bacterial meningitis."},{"id":"b","label":"Part B","prompt":"List 4 medications you might use to manage bacterial meningitis in this patient. Include\ndoses. For each, provide its clinical utility. (8 marks) Medication Clinical Utility You are considering performing a lumbar puncture to confirm the diagnosis."},{"id":"c","label":"Part C","prompt":"List 3 potential complications of lumbar puncture. For each, state how you will aim to\nprevent its occurrence. (6 marks) Complication Preventative measure A lumbar puncture has been performed. The results are provided below. CSF WBC 1820 *10^6/L (<5) Polymorphs 96%\nMononuclears 4%\nRBC 610 *10^6/L (<5)\n\nGlucose\n<0.3 mmol/L (2.2 - 3.9) Protein 9900 mg/L (150 - 500)"},{"id":"d","label":"Part D","prompt":"Interpret the result. (2 marks)"},{"id":"e","label":"Part E","prompt":"List 4 further tests you would perform to help with further management of this patient.\nFor each, provide justification. (4 marks) 1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Neck rigidity</div><div class=\"answer-line\">Photophobia</div><div class=\"answer-line\">Acute confusional state</div><div class=\"answer-line\">Decreased GCS ie obtundation</div><div class=\"answer-line\">Signs Raised Intracranial Pressure ie increased tone/hyperreflexia, hypertension, papilloedema</div><div class=\"answer-line\">Kernig / Brudzinski signs</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Dexamethasone 0.15mg/kg up to 10mg for all reduce mortality in Pneumococcus, reduce deafness</td><td><strong>Ceftriaxone 2gm IV or Cefotaxime 2gm IV as empiric therapy for all – treat pneumococcus, </strong></td></tr><tr><td><strong>meningococcus, haemophilus </strong></td><td>Benzylpenicillin 2.4gm IV or Trimethoprim-Suxamethoxazole 5 + 25mg/kg if Listeria</td></tr><tr><td>Vancomycin 30mg/kg if GPC on stain or Pneumococcal antigen pos</td><td>Moxifloxacin 400mg IV if anaphylaxis to penicillins or cephalosporins</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Spinal Cord/Nerve Injury – strategy use spinal needle, enter below cord (ie below L1 in adults)</td><td>Infection – sterile technique</td></tr><tr><td>Pain – copious local anaesthetic to skin and subcutaneous space down to interspinous ligament</td><td>Low pressure headache/CSF leak – small needle ie 25G with introducer, gentle technique</td></tr><tr><td>Bleeding – address any coagulopathy prior to puncture</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Bacterial Meningitis as evidenced by high PMNs, low glucose and high protein</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Urinary or CSF Ag testing for pneumococcus</td><td>Meningococcal PCR</td></tr><tr><td>Pneumococcal PCR testing</td><td>CSF Gram Stain</td></tr><tr><td>Blood Culture</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 7 year old girl has been brought to the ED after falling from a horse. She has an isolated left leg injury. There is a large wound over the mid-shin which has been dressed by the ambulance service. An AP x-ray of the left leg is provided below.","parts":[{"id":"a","label":"Part A","prompt":"Describe the abnormalities shown on the x-ray. (4 marks)"},{"id":"b","label":"Part B","prompt":"State 5 components of your management of this patient. (5 marks)\n1) 2) 3) 4) 5)"},{"id":"c","label":"Part C","prompt":"Complete the table for the Gustilo classification of compound fractures. (3 marks)"}],"propPages":["asset:img2f0051aed5af809370"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Complex lower leg fractures</div><div class=\"answer-line\">Midshaft comminuted tibial fracture with medial displacement of distal fragment (at least 80%)</div><div class=\"answer-line\">Tibial shortening</div><div class=\"answer-line\">Multilevel fibular fracture with medial displacement and shortening</div><div class=\"answer-line\">Lateral angulation 10-15 deg</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Analgesia eg IN Fentanyl 1.5mcg/kg, IV opiate with doses</div><div class=\"answer-line\">Consent for sedation/reduction</div><div class=\"answer-line\">Procedural sedation to facilitate</div><div class=\"answer-line\">Scrub and irrigate wounds</div><div class=\"answer-line\"><strong>Antibiotics for prophylaxis (cephazolin 50mg/kg up to 2gm) </strong></div><div class=\"answer-line\">Fracture reduction</div><div class=\"answer-line\"><strong>Immobilise in above knee cast </strong></div><div class=\"answer-line\">Elevated to decrease risk compartment syndrome</div><div class=\"answer-line\">Admit Orthopaedics for fixation</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Grade 1 – Open fracture with wound &lt;1cm and clean</div><div class=\"answer-line\">Grade 2 – Laceration &gt;1cm without extensive soft tissue damage</div><div class=\"answer-line\">Grade 3 – Extensive soft tissue injury</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 4 month old child has been brought to the ED with difficulty breathing.\nYou are considering the diagnosis of bronchiolitis.","parts":[{"id":"a","label":"Part A","prompt":"List 4 differential diagnoses. For each, state a discriminatory feature on history or\nexamination that would support its presence. (4 marks) Diagnosis Discriminatory feature on history or examination Your assessment is consistent with bronchiolitis."},{"id":"b","label":"Part B","prompt":"List 4 risk factors for more serious illness. (4 marks)\n1) 2) 3) 4)"},{"id":"c","label":"Part C","prompt":"List 3 treatment measures you might institute in the ED. For each, provide the clinical\nindication. (3 marks) Treatment Measure Clinical Indication"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Heart Failure – hepatomegaly, murmur</td><td>Pneumonia – focal crackles</td></tr><tr><td>Congenital Respiratory abnormalities -ie Congenital Lobar Emphysema – clinical hyperinflation, no bs</td><td>Tracheomalacia – stridor</td></tr><tr><td>Tracheo-oesophageal fistula – history of respiratory distress related to feeds</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Prematurity</div><div class=\"answer-line\">Known congenital lung disease</div><div class=\"answer-line\">Congenital heart disease</div><div class=\"answer-line\">Chronic neurological disease</div><div class=\"answer-line\">Timing of presentation (what day of illness)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Oxygenation therapy</strong> – indication Sats &lt;94%, marked work of breathing</td><td>HFNO2 2l/kg – failure to respond to supplemental O2 or signs severity</td></tr><tr><td>Intravenous fluids – inability to feed due to resp distress</td><td>NG feeds – alternate for inability to feed due to resp distress</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 65 year old quadriplegic man has presented with an episode of autonomic dysreflexia. He has been experiencing headache, sweating and facial flushing. His BP recorded at triage is 210/110 mmHg.","parts":[{"id":"a","label":"Part A","prompt":"List 5 potential causes of autonomic dysreflexia in this patient. For each, state how you\nwill assess for its presence. (5 marks) Cause Assessment feature"},{"id":"b","label":"Part B","prompt":"State 3 components of your management. (3 marks)\n1) 2) 3)"},{"id":"c","label":"Part C","prompt":"List 3 complications of autonomic dysreflexia that might be evident in the ED. (3 marks)\n1) 2) 3)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td><strong>Urinary retention</strong> – bladder scan &gt;500mls</td><td>Cystitis - urinalysis</td></tr><tr><td>Renal Colic – CT KUB if haematuria on urinalysis</td><td>Constipation – History of decreased bowel output, firm stool on PR exam</td></tr><tr><td>LL trauma  - LL assessment +/- xray imaging to areas with deformity/swelling</td><td>Pressure Sores – full log roll</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Positioning – sit patient up</div><div class=\"answer-line\">Release any tight clothing</div><div class=\"answer-line\">Treat cause ie drain bladder</div><div class=\"answer-line\"><strong>Vasodilators (ie GTN) to safely lower BP (caution re overshoot hypotension) </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Seizures</div><div class=\"answer-line\">Pulmonary Oedema</div><div class=\"answer-line\">Cerebral Haemorrhage</div><div class=\"answer-line\">Renal Failure</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 45 year old man has been transferred to your tertiary ED after being diagnosed with a myocardial infarction. He was thrombolysed prior to transfer. His ECG on arrival to your hospital is provided below.","parts":[{"id":"a","label":"Part A","prompt":"Provide your overall interpretation of the ECG with clinical significance, supported by 4 abnormalities. (6 marks) Overall interpretation (2 marks) ECG abnormalities (4 marks) 1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"State 3 factors you will consider in determining whether thrombolysis has been successful. (3 marks) 1) 2) 3)"},{"id":"c","label":"Part C","prompt":"List 3 complications of this presentation that might require additional management in the\nED. (3 marks) 1) 2) 3)"}],"propPages":["asset:imge5eb098c28d5658507"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Inferolateral STEMI</strong> with posterior and possible RV extension meeting reperfusion criteria</div><div class=\"answer-line\">Inferior STE III&gt;II</div><div class=\"answer-line\">STE V5-6</div><div class=\"answer-line\">STD I, aVL</div><div class=\"answer-line\">ST depression with early R waves and upright T waves V1-3 cf posterior MI</div><div class=\"answer-line\">Relative STE in V1 vs V2 cf RV infarction</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Time since thrombolysis</div><div class=\"answer-line\">Presence of ongoing pain</div><div class=\"answer-line\">ST segment resolution on 90min ECG at least 50%</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">AV block (ie CHB requiring chronotherapy)</div><div class=\"answer-line\">RV dysfunction requiring preload support ie IV fluids</div><div class=\"answer-line\">Malignant arrhythmia ie VT/VF</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"You will be reviewing a journal article as part of your department’s CME program. The article is a randomised controlled trial (RCT) of thrombolysis in stroke.","parts":[{"id":"a","label":"Part A","prompt":"List 4 limitations of RCTs. (4 marks)\n1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"Define “power” as it refers to analysis of a study. (1 mark)"},{"id":"c","label":"Part C","prompt":"List 3 determinants that are useful when calculating the appropriate sample size of a\nstudy. (3 marks) 1) 2) 3) The study reports its outcomes as a “number needed to treat”."},{"id":"d","label":"Part D","prompt":"List 4 other measures of association that may be used when reporting study outcomes.\n(4 marks) 1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">(Mainly revolve around applicability / translatability so allow several variations of this)</div><div class=\"answer-line\">Generalisability/Translatability to different environments</div><div class=\"answer-line\">Specific question studied may not be applicable to unique pt</div><div class=\"answer-line\">Unique time period assessment bias</div><div class=\"answer-line\">Background traits remain constant assumption</div><div class=\"answer-line\">Average treatment effects limitation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">is the ability that the study will detect a predetermined difference in measurement between the two</div><div class=\"answer-line\">groups</div><div class=\"answer-line\">“sensitivity” of hypothesis testing</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Effect size</div><div class=\"answer-line\">Degree of variation in variable measured</div><div class=\"answer-line\">Degree of certainty of result (significance)</div><div class=\"answer-line\">Desired power of study</div><div class=\"answer-line\">Likely distribution of data</div><div class=\"answer-line\">Others</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Odds ratio</div><div class=\"answer-line\">Relative risk reduction</div><div class=\"answer-line\">Absolute risk reduction</div><div class=\"answer-line\">Hazard ratio</div><div class=\"answer-line\">Number needed to harm</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"An 85 year old man has presented with hip pain after falling while doing his shopping.\nHe has a posteriorly dislocated total hip replacement. You intend to relocate the hip under procedural sedation.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your examination of this man that will inform your management of this\npatient in the ED. Provide the clinical significance of each. (4 marks) Examination feature Clinical significance"},{"id":"b","label":"Part B","prompt":"List 4 potential complications of performing procedural sedation on this man. For each,\nstate how you will prevent its occurrence. (8 marks) Complication Preventative Strategy"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Level of distress and response to analgesia – emergency reduction if unable to achieve comfort</div><div class=\"answer-line\"><strong>Vascular/ neurological status of leg</strong> – emergency reduction required if any impairment of blood</div><div class=\"answer-line\">supply or scitic nerve injury</div><div class=\"answer-line\">Presence of cardiorespiratory disease ie AS, Pulm HT, emphysema – will impact choice of sedative</div><div class=\"answer-line\">agents</div><div class=\"answer-line\">Airway assessment – may impact approach if patient has anatomically difficult airway or impaired</div><div class=\"answer-line\">neck mobility</div><div class=\"answer-line\">Vital signs – cause of fall might make sedation too risky immediately</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Respiratory Acidosis – use of capnography as evidence of prolonged apnoea</td><td>Hypoxia – pre-oxygenation, use of hi-flow O2 throughout</td></tr><tr><td>Awareness and pain – ensure adequate analgesia and clear communication between proceduralist</td><td>and sedation provider to ensure timeliness of painful reduction</td></tr><tr><td>Hypotension – fluid load, cautious use of titrated agents</td><td>Vomiting and aspiration – pre-treatment with antiemetic</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 40 year old woman has presented with heavy vaginal bleeding.","parts":[{"id":"a","label":"Part A","prompt":"State 4 key features of your history. Include the clinical relevance of each. (4 marks)\n1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"State 4 key features of your examination. Include the clinical relevance of each. (4 marks) 1) 2) 3) 4) Your provisional diagnosis is dysfunctional uterine bleeding."},{"id":"c","label":"Part C","prompt":"List 3 options for medical management, including doses. (3 marks)\n1) 2) 3)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">therapeutic options</div><div class=\"answer-line\">Presence of shoulder tip pain (may indicate ectopic even if unknown to be pregnant)</div><div class=\"answer-line\">Lots of others</div><div class=\"answer-line\">2.</div><div class=\"answer-line\"><strong>Abdominal exam –</strong> any features concerning for ectopic (lateralising tenderness or peritonism)</div><div class=\"answer-line\"><strong>Vital signs</strong> – tachycardia or hypotension indicate need for active management</div><div class=\"answer-line\">Postural blood pressure – marker of hypovolaemia and indicates need for treatment</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">in cervix requiring removal.</div><div class=\"answer-line\">Signs of thyroid disease – may point to cause</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Medroxyprogesterone 10mg tds</div><div class=\"answer-line\">Norethisterone 5-10mg tds</div><div class=\"answer-line\">Tranexamic acid 1gm tds</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 20 year old man has been struck to the right eye with a squash ball.\nA photograph of his eye is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State the diagnosis, with 3 supportive features. (4 marks) Diagnosis (1 mark) Supportive features (3 marks)"},{"id":"b","label":"Part B","prompt":"List 4 features of your examination, including the relevance of each. (4 marks)\n1) 2) 3) 4)"},{"id":"c","label":"Part C","prompt":"List 4 components of your management. (4 marks)\n1) 2) 3) 4)"}],"propPages":["asset:img92eaf1c550199e3364"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Traumatic Hyphaema</div><div class=\"answer-line\">Macrohyphaema with visible blood line</div><div class=\"answer-line\">Settled clot inferiorly</div><div class=\"answer-line\">Irregular pupil</div><div class=\"answer-line\">Conjunctival injection</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Visual Acuity</strong> – assess for injury to visual axis – lens, retina</div><div class=\"answer-line\">IOP – hyphaemia risk for acute angle closure and glaucoma</div><div class=\"answer-line\">Fluorescein staining – assess for corneal abrasion</div><div class=\"answer-line\">Extraocular movements-  concern for blowout fracture with entrapment</div><div class=\"answer-line\">Note EOM, IOP also concerning for retroorbital haematoma and proptosis would be ok here.</div><div class=\"answer-line\">Fundoscopy for retinal haemorrhage / traumatic detachment</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – drugs/doses</div><div class=\"answer-line\">Keep sitting up</div><div class=\"answer-line\">Antiemetics – drugs/doses</div><div class=\"answer-line\">Cycloplegics – cyclopentolate 1% eye drops</div><div class=\"answer-line\">Ophthalmology review</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
